class PaymentMethod {                    // interface
public:
    virtual bool pay(long long amount) = 0;
    virtual ~PaymentMethod() = default;
};
class Upi : public PaymentMethod {
public:
    bool pay(long long amount) override { /* call UPI gateway */ return true; }
};
class Card : public PaymentMethod {
public:
    bool pay(long long amount) override { /* call card network */ return true; }
};
void checkout(PaymentMethod& m, long long total) { m.pay(total); }   // depends only on the interface
```
